    for m in re.finditer(pattern, t):
        section_type = 'Demo' if 'demo' in pattern.lower() else 'Test'
        h, w = int(m.group(1)), int(m.group(2))
        start = m.end()
        remaining = t[start:start+5000]
        rows = [line.strip() for line in remaining.split('\n')[:min(h+5, 50)] if line.strip()]

        valid_rows = []
        for row in rows:
            parts = row.split()
            if len(parts) == w and all(x.isdigit() for x in parts):
                valid_rows.append(row)
            elif valid_rows:
                break

        sections.append({
            'type': section_type,
            'h': h,
            'w': w,
            'grid': [[int(x) for x in row.split()] for row in valid_rows]
        })

demo_in = sections[0]['grid']
