import json

def analyze_perfect_hollow(grid, color):
    """Check if shape is perfectly hollow (only border + empty interior)"""
    cells = [(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]

    if not cells:
        return False, None

    r_min, r_max = min(r for r,c in cells), max(r for r,c in cells)
    c_min, c_max = min(c for r,c in cells), max(c for r,c in cells)

    width = c_max - c_min + 1
    height = r_max - r_min + 1

    # Check every cell in bounding box
    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            val = grid[r][c]
            is_border = (r == r_min or r == r_max or c == c_min or c == c_max)

            if is_border:
                if val != color:
                    print(f"  Border gap at ({r},{c}): expected {color}, got {val}")
                    return False, {'width': width, 'height': height}
            else:
                if val != 0:
                    print(f"  Interior pixel at ({r},{c}): expected 0, got {val}")
                    return False, {'width': width, 'height': height}

    interior_area = (height - 2) * (width - 2)
    print(f"  Perfect hollow: {width}x{height}, interior area={interior_area}")
    return True, {'width': width, 'height': height, 'interior_area': interior_area}

