import json

def analyze_color_transformation(input_grid, output_grid, color):
    """Analyze what happened to a colored shape"""
    # Get original cells of this color
    cells_in = [(r,c) for r in range(len(input_grid)) for c in range(len(input_grid[0])) if input_grid[r][c] == color]

    if not cells_in:
        return {'error': 'Not found in input'}

    # Bounding box of input shape
    r_min_in, r_max_in = min(r for r,c in cells_in), max(r for r,c in cells_in)
    c_min_in, c_max_in = min(c for r,c in cells_in), max(c for r,c in cells_in)

    dims_in = (c_max_in - c_min_in + 1, r_max_in - r_min_in + 1)

    # Check each interior position - did any 0 become color?
    filled_positions = []
    erased_positions = []
    changed_other = []

    for r in range(r_min_in + 1, r_max_in):
        for c in range(c_min_in + 1, c_max_in):
            orig_val = input_grid[r][c]
            new_val = output_grid[r][c]

            if orig_val == 0 and new_val == color:
                filled_positions.append((r,c))
            elif orig_val == color and new_val == 0:
                erased_positions.append((r,c))
            elif orig_val == color and new_val != color:
                changed_other.append((r,c))

    total_interior = len(filled_positions) + len(erased_positions) + len(changed_other)

    # Also check overall shape existence
    cells_out = [(r,c) for r in range(len(output_grid)) for c in range(len(output_grid[0])) if output_grid[r][c] == color]

    if not cells_out:
        status = "COMPLETELY_GONE"
    elif len(cells_out) < len(cells_in):
        status = "PARTIALLY_ERASED"
    else:
        status = "PRESERVED"

    return {
        'color': color,
        'status': status,
        'input_cells': len(cells_in),
        'output_cells': len(cells_out),
        'dims_in': dims_in,
        'filled_interior_count': len(filled_positions),
        'filled_positions': filled_positions[:5],
        'erased_from_interior': len(erased_positions)
    }

