def classify_rectangle(demo_in, demo_out):
    """Classify each shape: dims, border ok, filled/erased/preserved"""
    all_colors = set()
    for r in range(len(demo_in)):
        for c in range(len(demo_in[0])):
            val = demo_in[r][c]
            if val != 0:
                all_colors.add(val)

    classifications = []
    for color in sorted(all_colors):
        cells = [(r,c) for r in range(len(demo_in)) for c in range(len(demo_in[0])) if demo_in[r][c] == color]
        if not cells:
            continue

        r_min, r_max = min(r for r,c in cells), max(r for r,c in cells)
        c_min, c_max = min(c for r,c in cells), max(c for r,c in cells)
        dims = (c_max-c_min+1, r_max-r_min+1)

        # Check border
        def is_border_ok():
            for r in range(r_min, r_max + 1):
                for c in range(c_min, c_max + 1):
                    val = demo_in[r][c]
                    if (r == r_min or r == r_max or c == c_min or c == c_max) and val != color:
                        return False
            return True

        if not is_border_ok():
            status = "NOT_PERFECT_HOLLOW"
        else:
            # Count interior changes
            filled_count = 0
            erased_count = 0
            for r in range(r_min + 1, r_max):
                for c in range(c_min + 1, c_max):
                    orig = demo_in[r][c]
                    new = demo_out[r][c]
                    if orig == 0 and new == color:
                        filled_count += 1
                    elif orig == color and new == 0:
                        erased_count += 1

            if filled_count > 0 and erased_count == 0:
                status = "FILLED"
            elif filled_count == 0 and erased_count > 0:
                status = "ERASED"
            elif filled_count > 0 and erased_count > 0:
                status = "MODIFIED"
            else:
                status = "PRESERVED"

        interior_cells = (dims[0]-2) * (dims[1]-2) if dims[0]>2 and dims[1]>2 else 0
        colored_interior = sum(1 for r in range(r_min+1,r_max) for c in range(c_min+1,c_max) if demo_in[r][c] == color)
        empty_interior = interior_cells - colored_interior

        classifications.append({
            'color': color,
            'dims': dims,
            'status': status,
            'hollow': empty_interior,
            'interior_area': interior_cells,
            'ratio': empty_interior / interior_cells if interior_cells > 0 else None
        })

    return classifications

