def apply_transformation_rule(demo_in):
    """Apply transformation rule based on analysis"""
    rows = len(demo_in)
    cols = len(demo_in[0])
    output = [[demo_in[r][c] for c in range(cols)] for r in range(rows)]

    visited = set()
    for r in range(rows):
        for c in range(cols):
            val = demo_in[r][c]
            if val != 0 and (r,c) not in visited:
                cells = [(rr,cc) for rr in range(rows) for cc in range(cols) 
                        if demo_in[rr][cc] == val]
                r_min, r_max = min(rr for rr,cc in cells), max(rr for rr,cc in cells)
                c_min, c_max = min(cc for rr,cc in cells), max(cc for rr,cc in cells)

                w = c_max - c_min + 1
                h = r_max - r_min + 1

                def is_perfect_hollow():
                    # Check border complete and no interior pixels of same color
                    for cc in range(c_min, c_max+1):
                        if demo_in[r_min][cc] != val or demo_in[r_max][cc] != val:
                            return False
                    for rr in range(r_min, r_max+1):
                        if demo_in[rr][c_min] != val or demo_in[rr][c_max] != val:
                            return False
                    for rr in range(r_min+1, r_max):
                        for cc in range(c_min+1, c_max):
                            if demo_in[rr][cc] == val:
                                return False
                    return True

                int_w = w - 2
                int_h = h - 2
                interior_cells = int_w * int_h

                if is_perfect_hollow():
                    # Rule: Interior cells >= 10 AND both dims >= 6 => PRESERVE (fill interior with background)
                    # Else: Fill interior with color

                    if interior_cells >= 10 and int_w >= 6 and int_h >= 6:
                        # Preserve border, fill interior with background (erase interior)
                        for rr in range(r_min+1, r_max):
                            for cc in range(c_min+1, c_max):
                                output[rr][cc] = 0  # Erase interior

                    elif interior_cells < 6:
                        # Very small - erase entire shape including border
                        for rr in range(r_min, r_max+1):
                            for cc in range(c_min, c_max+1):
                                output[rr][cc] = 0

                    else:
                        # Standard case: Fill interior with color
                        for rr in range(r_min+1, r_max):
                            for cc in range(c_min+1, c_max):
                                if demo_in[rr][cc] == 0:
                                    output[rr][cc] = val

    return output

