                border_ok = False
        if not border_ok:
            is_hollow = False

        area = w * h

        # Result
        new_count = sum(1 for r in range(r_min, r_max+1) for c in range(c_min, c_max+1) 
                       if demo_out[r][c] != 0)
        old_count = new_count  # Same as above
        filled_cells = sum(1 for r in range(r_min+1, r_max) for c in range(c_min+1, c_max) 
                          if demo_out[r][c] == color_val and demo_in[r][c] == 0)

        if filled_cells > 0:
            result = "FILLED"
        elif new_count == 0:
            result = "ERASED"
        else:
            result = "PRESERVED"

        print(f"{color_val:<6} {w:<4} {h:<4} {area:<6} {str(is_hollow):<8} {result}")

for name, din, dout in [('D1', demo_in_1, demo_out_1), ('D2', demo_in_2, demo_out_2), ('D3', demo_in_3, demo_out_3)]:
    analyze_all_colors(din, dout, name)
